ServerEvents.recipes(event => {
  let n = 0
  for (let [tag, fam] of Object.entries(INTEGRATION_FAMILIES)) {
    if (!Item.exists(fam.canonical)) continue
    for (let alias of fam.aliases) {
      if (!Item.exists(alias)) continue
      event.replaceOutput({}, alias, fam.canonical)
      event.replaceInput({}, alias, '#' + tag)
      event.shapeless(fam.canonical, [alias]).id('diaithir_integration:unify/' + alias.replace(':', '/'))
      n++
    }
  }
  console.info('[integration] unified ' + n + ' aliases')
  // what the generated data pack added, by recipe type (tools/integration/validate.py is the static check, this is the live one)
  let byType = {}, total = 0
  event.forEachRecipe({ id: /^diaithir_integration:/ }, r => {
    total++
    let t = String(r.json.get('type').getAsString())
    byType[t] = (byType[t] || 0) + 1
  })
  console.info('[integration] ' + total + ' recipes from diaithir_integration: ' + JSON.stringify(byType))
})
